/**
 * Toggle — generated by the React Native Reusables CLI (`toggle`, pulled in by
 * `toggle-group`), re-skinned.
 *
 * Deviations from upstream, kept here so the next `add toggle --overwrite` diff reads:
 * - Pressed is a readout, not the accent: a `card` face with a strong hairline
 *   edge and full-ink text, against `muted-foreground` at rest. Upstream fills
 *   `bg-accent` (shadcn's hover token, which this palette does not have) and that
 *   would spend the screen's one accent on a state (docs/design-guidelines.md).
 * - Presses go to `muted`; `outline` is a hairline on `border-input` with no
 *   `shadow-sm shadow-black/5` — depth here goes through `useElevation`, and a
 *   pressed state is not lifted.
 * - The web string loses `focus-visible:ring-ring/50`, the `aria-invalid` rings
 *   and their `dark:` twin: opacity modifiers do nothing on hex variables and the
 *   variables already follow the theme.
 * - Sizes are touch sizes: 48 is the default and the minimum target; the `sm:`
 *   desktop steps are removed and padding uses only `space` steps.
 */
import { Icon } from '@/components/ui/icon';
import { TextClassContext } from '@/components/ui/text';
import { cn } from '@/lib/utils';
import * as TogglePrimitive from '@rn-primitives/toggle';
import { cva, type VariantProps } from 'class-variance-authority';
import * as React from 'react';
import { Platform } from 'react-native';

const toggleVariants = cva(
  cn(
    'group flex flex-row items-center justify-center gap-2 rounded-md border border-transparent active:bg-muted',
    Platform.select({
      web: 'focus-visible:ring-ring inline-flex cursor-default whitespace-nowrap outline-none focus-visible:ring-2 disabled:pointer-events-none [&_svg]:pointer-events-none',
    }),
  ),
  {
    variants: {
      variant: {
        default: 'bg-transparent',
        outline: 'border-input bg-transparent',
      },
      size: {
        default: 'h-12 min-w-12 px-4',
        sm: 'h-10 min-w-10 px-2',
        lg: 'h-14 min-w-14 px-4',
      },
    },
    defaultVariants: {
      variant: 'default',
      size: 'default',
    },
  },
);

/** The pressed face shared with `ToggleGroupItem`: a readout, never an accent fill. */
const togglePressedClass = 'border-border-strong bg-card';

/** Label ink for a toggle: full ink when pressed, muted at rest. */
function toggleTextClass(pressed: boolean | undefined): string {
  return cn('font-sans text-sm font-medium', pressed ? 'text-foreground' : 'text-muted-foreground');
}

function Toggle({
  className,
  variant,
  size,
  ...props
}: React.ComponentProps<typeof TogglePrimitive.Root> & VariantProps<typeof toggleVariants>) {
  return (
    <TextClassContext.Provider value={cn(toggleTextClass(props.pressed), className)}>
      <TogglePrimitive.Root
        className={cn(
          toggleVariants({ variant, size }),
          props.disabled && 'opacity-50',
          props.pressed && togglePressedClass,
          className,
        )}
        {...props}
      />
    </TextClassContext.Provider>
  );
}

function ToggleIcon({ className, ...props }: React.ComponentProps<typeof Icon>) {
  const textClass = React.useContext(TextClassContext);
  return <Icon className={cn('size-4 shrink-0', textClass, className)} {...props} />;
}

export { Toggle, ToggleIcon, togglePressedClass, toggleTextClass, toggleVariants };
